python3 -c '
import os, re

for root, dirs, files in os.walk("src"):
    for f in files:
        if f.endswith((".h", ".cpp")):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()
            ns_idx = content.find("namespace uvm")
            if ns_idx != -1:
                prefix = content[:ns_idx]
                matches = re.findall(r"class\s+uvm_\w+", prefix)
                if matches:
                    print(f"{path}: {matches}")
'

